MOD = 1000003

def count_paths(Y, X, x_init, grid):
    dp = [[0] * X for _ in range(Y)]
    dp[Y-1][x_init] = 1

    for y in range(Y-1, -1, -1):
        for x in range(X):
            if grid[y][x] == '#':
                continue
            if y + 1 < Y and grid[y+1][x] != '#':
                dp[y][x] = (dp[y][x] + dp[y+1][x]) % MOD
            if x + 1 < X and grid[y][x] == '>' and grid[y][x+1] != '#' and grid[y][x+1] != '<':
                dp[y][x] = (dp[y][x] + dp[y][x+1]) % MOD
            if x - 1 >= 0 and grid[y][x] == '<' and grid[y][x-1] != '#' and grid[y][x-1] != '>':
                dp[y][x] = (dp[y][x] + dp[y][x-1]) % MOD

    return dp[0].count('@')

import sys
input = sys.stdin.read
data = input().split()

Y = int(data[0])
X = int(data[1])
x_init = int(data[2])
grid = data[3:]

result = count_paths(Y, X, x_init, grid)
if result == 0:
    print("begin repairs")
else:
